"""Host-side scorer for phys-contact-solver (A-pattern).

The eval emits only IMPULSES (`FINAL_IMPULSES:`), never a score. This parser
imports the host-only `dgp` -- `holdout/phys-contact-solver/dgp.py` in the dev
tree, `tests/meta/dgp.py` in a Harbor bundle -- loads the HELD-OUT contact
problems, and recomputes the self-certifying NCP residual itself. Nothing the
container prints can become the recorded number.
"""
import base64
import importlib.util
import io
import re
import sys
from pathlib import Path

# Only reach for the repo checkout when mlsbench is genuinely absent.
# Under Harbor this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/,
# so a __file__-derived PROJECT_ROOT is /tmp and this would put an
# agent-writable directory at the front of the verifier's sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent / "src"))
from mlsbench.agent.parsers import OutputParser, ParseResult
from mlsbench.holdout import load_holdout_module  # noqa: E402

_MARKER = "FINAL_IMPULSES:"


def _load_dgp():
    """Load the sealed holdout module.  Never a __file__-parents path:
    see src/mlsbench/holdout.py for why.  The call site treats None as
    "not scoreable", so the missing-module case stays a None."""
    try:
        return load_holdout_module("phys-contact-solver", __file__)
    except ImportError:
        return None


class Parser(OutputParser):
    def parse(self, cmd_label, raw_output):
        setting = cmd_label.replace("-", "_")
        fb, metrics = [], {}
        finals = [l.strip() for l in raw_output.splitlines() if l.strip().startswith(_MARKER)]
        if not finals:
            return ParseResult(
                feedback=f"No {_MARKER} line ({cmd_label}); the run did not complete.\n"
                         + raw_output[-1500:], metrics={})
        if len(finals) != 1:
            # Exactly one: the launcher prints it once and the eval script
            # appends that one line to the result file. Never last-wins.
            return ParseResult(
                feedback=f"{len(finals)} {_MARKER} lines ({cmd_label}); expected exactly one.",
                metrics={})
        last = finals[0]
        if "INVALID" in last:
            return ParseResult(feedback=f"Run INVALID ({cmd_label}): {last}", metrics={})
        dgp = _load_dgp()
        if dgp is None:
            return ParseResult(feedback=f"dgp unavailable host-side ({cmd_label}).", metrics={})
        m = re.search(r"data=([A-Za-z0-9+/=]+)", last)
        if not m:
            return ParseResult(feedback=f"No impulse payload ({cmd_label}).", metrics={})
        try:
            import numpy as np
            z = np.load(io.BytesIO(base64.b64decode(m.group(1))))
            lams = [z[lab] for lab in dgp.scored_labels(setting)]
        except Exception as exc:
            return ParseResult(feedback=f"Undecodable impulses ({cmd_label}): {exc!r}", metrics={})
        res = dgp.score_setting(setting, lams)
        eps = res["eps_abs"]
        if eps != eps or eps in (float("inf"),):     # NaN / inf -> unscorable
            return ParseResult(
                feedback=f"Non-finite residual ({cmd_label}); per-instance {res['per_instance']}",
                metrics={})
        metrics[f"eps_abs_{setting}"] = float(eps)
        cpu = re.search(r"cpu_ms=([\d.]+)", last)
        if cpu:
            metrics[f"cpu_ms_{setting}"] = float(cpu.group(1))
        fb.append(f"{setting}: eps_abs(gmean over {len(res['per_instance'])} held-out problems)"
                  f" = {eps:.4e}")
        fb.append("  per-instance: " + ", ".join(f"{p:.3e}" for p in res["per_instance"]))
        return ParseResult(feedback="\n".join(fb), metrics=metrics)
